--- a/src/knownhost.c
+++ b/src/knownhost.c
@@ -521,14 +521,22 @@ static int knownhost_ipv6_part(const char *host, const char **address,
         const char *close = strchr(host + 1, ']');
         const char *port;

-        if(!close || close == host + 1 || close[1] != ':' || !close[2])
+        if(!close || close == host + 1)
             return 0;

-        port = close + 2;
-        while(*port) {
-            if(*port < '0' || *port > '9')
+        port = close + 1;
+        if(*port) {
+            /* the port suffix is optional, but when present it must be
+               ':' followed by digits only */
+            if(*port != ':' || !port[1])
                 return 0;
+
             port++;
+            while(*port) {
+                if(*port < '0' || *port > '9')
+                    return 0;
+                port++;
+            }
         }

         *address = host + 1;

